CREATE OR REPLACE FUNCTION public.lead_daily_quota_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare lim integer; used integer; owner_id uuid; plan_name text; begin select r.user_id into owner_id from public.lead_daily_generation_requests r where r.id=new.request_id; if owner_id is null or owner_id<>new.user_id then raise exception 'request owner mismatch'; end if; select case when p.subscription_status in ('active','trialing') then coalesce(p.plan,'free') else 'free' end into plan_name from public.profiles p where p.id=owner_id; select case when new.contact_kind='klaviyo' then q.klaviyo_daily_limit else q.professional_daily_limit end into lim from public.lead_plan_quotas q where q.plan_code=coalesce(plan_name,'free'); if lim is null then plan_name := 'free'; select case when new.contact_kind='klaviyo' then q.klaviyo_daily_limit else q.professional_daily_limit end into lim from public.lead_plan_quotas q where q.plan_code='free'; end if; if lower(coalesce(plan_name,'free')) in ('free','gratuit') and not exists (select 1 from public.lead_team_memberships m where m.user_id=owner_id and m.status='verified') and not exists (select 1 from public.profiles p where p.id=owner_id and p.is_admin is true and p.account_status is distinct from 'suspended') then raise exception 'verified lead team membership required'; end if; if lim is null or lim<=0 then raise exception 'daily quota unavailable'; end if; select count(*) into used from public.lead_daily_allocations where request_id=new.request_id and contact_kind=new.contact_kind; if used>=lim then raise exception 'daily quota exceeded'; end if; return new; end $function$;
